/* Tier 1: primitives (done) */
:root {
  --nw-blue-600: #1f5ae0;
  --nw-blue-700: #1848b8;
  --nw-white: #ffffff;
  --nw-space-2: 0.5rem;
  --nw-space-4: 1rem;
}

/* Tier 2: semantic tokens */
:root {
  --nw-color-action-bg: var(--nw-blue-600);
  --nw-color-action-text: var(--nw-white);
}

/* Tier 3: component tokens, declared on the component */
.nw-button {
  --nw-button-bg: var(--nw-color-action-bg);
  --nw-button-text: var(--nw-color-action-text);

  background: var(--nw-button-bg);
  color: var(--nw-button-text);
  padding: var(--nw-space-2) var(--nw-space-4);
  border: 0;
  border-radius: 6px;
  font: inherit;
}
.promo { margin-top: 16px; }
